from __future__ import annotations

import tempfile
import unittest
from pathlib import Path

from harness.source_policy.cleaner import clean_repository, clean_source
from harness.source_policy.policy import Policy, classify_comment, is_exempt_path
from harness.source_policy.scanner import analyze_file


class PolicyClassificationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.policy = Policy()

    def test_ordinary_comment_is_prohibited(self) -> None:
        decision = classify_comment("// explain the business rule", 40, self.policy)
        self.assertTrue(decision.prohibited)
        self.assertEqual(decision.category, "ORDINARY_COMMENT")

    def test_license_header_is_preserved(self) -> None:
        decision = classify_comment("/* Copyright 2024 Acme\n * Licensed under the Apache License */", 2, self.policy)
        self.assertFalse(decision.prohibited)
        self.assertEqual(decision.category, "LICENSE_HEADER")

    def test_generated_marker_is_preserved(self) -> None:
        decision = classify_comment("// Generated by openapi generator", 1, self.policy)
        self.assertFalse(decision.prohibited)
        self.assertEqual(decision.category, "GENERATED_MARKER")

    def test_tooling_directive_is_preserved(self) -> None:
        decision = classify_comment("// CHECKSTYLE:OFF", 100, self.policy)
        self.assertFalse(decision.prohibited)
        self.assertEqual(decision.category, "TOOLING_DIRECTIVE")

    def test_sourcemap_directive_is_preserved(self) -> None:
        decision = classify_comment("//# sourceMappingURL=app.js.map", 1, self.policy)
        self.assertFalse(decision.prohibited)
        self.assertEqual(decision.category, "SOURCEMAP_DIRECTIVE")

    def test_shebang_is_preserved(self) -> None:
        decision = classify_comment("#!/usr/bin/env bash", 1, self.policy)
        self.assertFalse(decision.prohibited)
        self.assertEqual(decision.category, "SHEBANG")

    def test_todo_marker_is_prohibited(self) -> None:
        decision = classify_comment("// TODO: refactor later", 10, self.policy)
        self.assertTrue(decision.prohibited)

    def test_license_outside_header_budget_is_preserved(self) -> None:
        decision = classify_comment("// Copyright notice retained", 900, self.policy)
        self.assertFalse(decision.prohibited)

    def test_generated_path_is_exempt(self) -> None:
        self.assertTrue(is_exempt_path("order-service/target/generated/Foo.java", self.policy))
        self.assertFalse(is_exempt_path("order-service/src/main/java/Foo.java", self.policy))


class SourceAnalysisTest(unittest.TestCase):
    def setUp(self) -> None:
        self.temporary = tempfile.TemporaryDirectory()
        self.root = Path(self.temporary.name)
        self.policy = Policy()

    def tearDown(self) -> None:
        self.temporary.cleanup()

    def _write(self, name: str, content: str) -> Path:
        path = self.root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        return path

    def test_analysis_reports_file_and_line(self) -> None:
        path = self._write("Sample.java", "package a;\n\n// note\nclass Sample {}\n")
        report = analyze_file(path, "Sample.java", self.policy)
        self.assertEqual(len(report.prohibited), 1)
        self.assertEqual(report.prohibited[0].line, 3)
        self.assertEqual(report.total_comments, 1)

    def test_analysis_preserves_license_and_flags_ordinary(self) -> None:
        content = "/* Copyright 2024 Acme */\n// ordinary note\nclass Sample {}\n"
        path = self._write("Sample.java", content)
        report = analyze_file(path, "Sample.java", self.policy)
        self.assertEqual(len(report.preserved), 1)
        self.assertEqual(len(report.prohibited), 1)

    def test_clean_removes_only_prohibited_comments(self) -> None:
        content = "/* Copyright 2024 Acme */\n// ordinary note\nclass Sample {}\n"
        path = self._write("Sample.java", content)
        cleaned, outcome = clean_source(path, "Sample.java", content, self.policy)
        self.assertIn("Copyright 2024 Acme", cleaned)
        self.assertNotIn("ordinary note", cleaned)
        self.assertIn("class Sample {}", cleaned)
        self.assertTrue(outcome.changed)

    def test_clean_preserves_string_literal_with_comment_markers(self) -> None:
        content = 'class Sample { String url = "http://x//y"; }\n'
        path = self._write("Sample.java", content)
        cleaned, outcome = clean_source(path, "Sample.java", content, self.policy)
        self.assertEqual(cleaned, content)
        self.assertFalse(outcome.changed)

    def test_clean_drops_lines_that_become_empty(self) -> None:
        content = "class Sample {\n    // note\n    void run() {}\n}\n"
        path = self._write("Sample.java", content)
        cleaned, outcome = clean_source(path, "Sample.java", content, self.policy)
        self.assertNotIn("// note", cleaned)
        self.assertIn("void run() {}", cleaned)
        self.assertEqual(outcome.removed_lines, 1)

    def test_clean_keeps_code_on_a_line_with_a_trailing_comment(self) -> None:
        content = "class Sample { void run() {} } // note\n"
        path = self._write("Sample.java", content)
        cleaned, outcome = clean_source(path, "Sample.java", content, self.policy)
        self.assertIn("void run() {}", cleaned)
        self.assertNotIn("// note", cleaned)

    def test_clean_repository_dry_run_does_not_write(self) -> None:
        path = self._write("Sample.java", "// note\nclass Sample {}\n")
        result = clean_repository(["Sample.java"], self.root, self.policy, dry_run=True)
        self.assertEqual(result["changed_files"], 1)
        self.assertIn("// note", path.read_text(encoding="utf-8"))

    def test_clean_repository_writes_when_not_dry_run(self) -> None:
        path = self._write("Sample.java", "// note\nclass Sample {}\n")
        result = clean_repository(["Sample.java"], self.root, self.policy, dry_run=False)
        self.assertEqual(result["changed_files"], 1)
        self.assertNotIn("// note", path.read_text(encoding="utf-8"))

    def test_clean_repository_reports_missing_file(self) -> None:
        result = clean_repository(["Absent.java"], self.root, self.policy)
        self.assertEqual(result["outcomes"][0]["error"], "file not found")

    def test_yaml_hash_comment_is_removed_but_quoted_hash_is_kept(self) -> None:
        content = "key: value # trailing comment\nother: \"a # b\"\n"
        path = self._write("application.yaml", content)
        cleaned, outcome = clean_source(path, "application.yaml", content, self.policy)
        self.assertNotIn("trailing comment", cleaned)
        self.assertIn('"a # b"', cleaned)

    def test_sql_dash_comment_is_removed(self) -> None:
        content = "SELECT 1 -- trailing\nFROM t;\n"
        path = self._write("query.sql", content)
        cleaned, outcome = clean_source(path, "query.sql", content, self.policy)
        self.assertNotIn("trailing", cleaned)
        self.assertIn("FROM t;", cleaned)

    def test_exempt_path_is_not_modified(self) -> None:
        content = "// note\nclass Sample {}\n"
        path = self._write("target/generated/Sample.java", content)
        cleaned, outcome = clean_source(path, "target/generated/Sample.java", content, self.policy)
        self.assertEqual(cleaned, content)
        self.assertFalse(outcome.changed)


if __name__ == "__main__":
    unittest.main()
